// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint96 amount1, uint96 amount2, address actor) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(uint256(amount1) + uint256(amount2) < address(actor).balance + 1e30);
        vm.deal(actor, uint256(amount1) + uint256(amount2));

        vm.startPrank(actor);
        c.Put{value: amount1}(0);
        c.Put{value: amount2}(0);
        vm.stopPrank();

        (, uint256 balance) = c.Acc(actor);
        assertTrue(balance == uint256(amount1) + uint256(amount2));
    }
}
